  if z>0:
   pcam=np.array([(u-K[0,2])*z/K[0,0],(v-K[1,2])*z/K[1,1],z,1]);w=inv@pcam
   print((u,v),rgb.tolist(),round(float(z),3),np.round(w[:3],3))
print('tcp',m['proprio']['now'][16:23])
